site.css:
/* The Seventh Bell player handouts: one shared look. One readable column, standard fonts, tables and lists. Inlined into each page by build-handouts.cjs. */
:root{--bg:#fbfaf6;--surface:#f2efe7;--text:#1e2125;--muted:#565b62;--line:#d8d3c7;--accent:#7a5418;--serif:Georgia,"Times New Roman",serif;--sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#17191c;--surface:#212428;--text:#e8e5de;--muted:#aca79d;--line:#383c42;--accent:#d9b26a;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#17191c;--surface:#212428;--text:#e8e5de;--muted:#aca79d;--line:#383c42;--accent:#d9b26a;color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font:17px/1.6 var(--sans);padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:2.5rem 4rem}
main{max-width:46rem;margin:0 auto}
h1,h2,h3{font-family:var(--serif);line-height:1.2;text-wrap:balance}
h1{font-size:2.5rem;margin:0 0 .4rem}
h2{font-size:1.55rem;margin:2.6rem 0 .8rem;padding-top:1.4rem;border-top:1px solid var(--line)}
h3{font-size:1.15rem;margin:1.6rem 0 .3rem}
p{margin:0 0 1rem}
ul,ol{margin:0 0 1rem;padding-left:1.3rem}
li{margin-bottom:.35rem}
a{color:var(--accent)}
.subtitle{color:var(--muted);margin-bottom:1.5rem}
.facts{display:flex;flex-wrap:wrap;gap:.4rem 1.5rem;margin:0 0 1.5rem;padding:0;list-style:none;color:var(--muted);font-size:.95rem}
.facts b{color:var(--text)}
.box,.contents,.set{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:1rem 1.2rem;margin:0 0 1rem}
.box p:last-child,.box ul:last-child,.set p:last-child{margin-bottom:0}
.contents p,.set p.label{margin:0 0 .4rem;font-weight:600}
.contents ol{margin:0;columns:2 14rem}
.set ol{margin:0;padding-left:1.3rem}
.set li{margin-bottom:.2rem}
.set .here b{font-weight:600}
.table-wrap{overflow-x:auto;margin:0 0 1rem}
table{width:100%;border-collapse:collapse;font-size:.95rem}
table.wide{min-width:34rem}
th,td{padding:.55rem .6rem;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{background:var(--surface);font-weight:600}
td.num{white-space:nowrap;font-variant-numeric:tabular-nums}
dl{margin:0 0 1rem}
dt{font-weight:600;margin-top:.7rem}
dd{margin:0}
.sounds{color:var(--muted);font-style:italic}
.closing{font-family:var(--serif);font-size:1.4rem;text-align:center;margin:2.5rem 0 .5rem}
figure{margin:0 0 1rem}
figcaption{color:var(--muted);font-size:.9rem;margin-top:.4rem}
.map{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
footer{margin-top:3rem;padding-top:1rem;border-top:1px solid var(--line);color:var(--muted);font-size:.9rem}
